drop policy order_documents_add on public.order_documents;
create policy order_documents_add on public.order_documents for insert to authenticated with check (uploaded_by=(select auth.uid()) and public.can_access_warehouse(warehouse_id) and public.current_user_role() in ('admin','warehouse_manager','warehouse_staff','delivery') and ((inbound_order_id is not null and exists(select 1 from public.inbound_orders i where i.id=order_documents.inbound_order_id and i.warehouse_id=order_documents.warehouse_id)) or (delivery_order_id is not null and exists(select 1 from public.delivery_orders d join public.outbound_orders o on o.id=d.outbound_order_id where d.id=order_documents.delivery_order_id and o.warehouse_id=order_documents.warehouse_id))));
